from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_upload_time(value: Any) -> datetime | None:
    """Parse an ``upload_time_iso_8601`` value, returning ``None`` if invalid."""
    if not isinstance(value, str) or not value:
        return None
    # ``datetime.fromisoformat`` on older Python versions does not accept the
    # trailing ``Z`` used by PyPI, so normalize it to an explicit UTC offset.
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version)."""

    version: Version
    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_distributions(
        cls, version: Version, distributions: list[dict[str, Any]]
    ) -> Release | None:
        """Build a :class:`Release` from the distribution files of one version.

        Returns ``None`` when the release should be dropped, i.e. when it has no
        distributions or none of them carry a parseable ``upload_time_iso_8601``.
        """
        if not distributions:
            return None

        upload_times = [
            t
            for dist in distributions
            if (t := _parse_upload_time(dist.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is only considered yanked when *every* distribution for it is
        # yanked. If any distribution is not yanked, the release is not yanked.
        yanked = all(bool(dist.get("yanked", False)) for dist in distributions)

        requires_python: SpecifierSet | None = None
        for dist in distributions:
            raw = dist.get("requires_python")
            if not raw or not isinstance(raw, str):
                continue
            try:
                requires_python = SpecifierSet(raw)
            except InvalidSpecifier:
                continue
            break

        return cls(
            version=version,
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass(frozen=True)
class Package:
    """Typed representation of a PyPI package and its releases."""

    name: str
    releases: dict[Version, Release]

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        """Parse a PyPI JSON API response into a :class:`Package`."""
        name = str(data.get("info", {}).get("name", ""))
        raw_releases = data.get("releases", {}) or {}

        releases: dict[Version, Release] = {}
        for version_str, distributions in raw_releases.items():
            try:
                version = Version(version_str)
            except InvalidVersion:
                continue
            release = Release.from_distributions(version, distributions or [])
            if release is None:
                continue
            releases[version] = release

        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        """All valid release versions, sorted in ascending order."""
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        """The highest stable, non-yanked version, or ``None`` if none exists."""
        for version in sorted(self.releases, reverse=True):
            if version.is_prerelease or version.is_devrelease:
                continue
            if self.releases[version].yanked:
                continue
            return version
        return None

    def get_release(self, version: str | Version) -> Release | None:
        """Return the :class:`Release` for ``version``, or ``None`` if absent."""
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
