from __future__ import annotations

import asyncio
import json
import os
import time
import urllib.error
import urllib.request
from typing import Any, Iterable

from pypi._models import Package

# Default PyPI base URL, overridable via the ``PYPI_URL`` environment variable.
_DEFAULT_BASE_URL = "https://pypi.org"

# HTTP status codes that represent transient failures worth retrying.
_TRANSIENT_STATUS_CODES = frozenset({429, 500, 502, 503, 504})

# Maximum total number of attempts (initial request + retries).
_MAX_ATTEMPTS = 3

# In-memory cache mapping package name -> parsed ``Package``.
_CACHE: dict[str, Package] = {}


class PyPIError(RuntimeError):
    """Raised for all unrecoverable errors when fetching from PyPI."""


def _base_url() -> str:
    base = os.environ.get("PYPI_URL") or _DEFAULT_BASE_URL
    return base.rstrip("/")


def _build_url(name: str) -> str:
    return f"{_base_url()}/pypi/{name}/json"


def _fetch_json(name: str) -> dict[str, Any]:
    """Fetch and parse the PyPI JSON metadata for ``name``.

    Retries transient HTTP and network errors up to ``_MAX_ATTEMPTS`` times.
    """
    url = _build_url(name)
    last_error: BaseException | None = None

    for attempt in range(_MAX_ATTEMPTS):
        try:
            with urllib.request.urlopen(url) as response:
                body = response.read()
            data = json.loads(body)
            if not isinstance(data, dict):
                raise PyPIError(
                    f"Unexpected response for package {name!r}: "
                    f"expected a JSON object, got {type(data).__name__}"
                )
            return data
        except urllib.error.HTTPError as e:
            if e.code == 404:
                raise PyPIError(f"Package not found: {name!r}") from e
            if e.code in _TRANSIENT_STATUS_CODES:
                last_error = e
            else:
                raise PyPIError(
                    f"HTTP {e.code} error while fetching package {name!r}"
                ) from e
        except (urllib.error.URLError, ConnectionResetError) as e:
            last_error = e

        if attempt < _MAX_ATTEMPTS - 1:
            time.sleep(2**attempt)

    raise PyPIError(
        f"Failed to fetch package {name!r} after {_MAX_ATTEMPTS} attempts"
    ) from last_error


def get_package(name: str) -> Package:
    """Fetch package metadata from PyPI, memoizing results in memory."""
    if name in _CACHE:
        return _CACHE[name]
    package = Package.from_json(_fetch_json(name))
    _CACHE[name] = package
    return package


def clear_cache() -> None:
    """Clear the in-memory cache used by :func:`get_package`."""
    _CACHE.clear()


async def aget_package(name: str) -> Package:
    """Async wrapper around :func:`get_package`."""
    return await asyncio.to_thread(get_package, name)


async def aget_packages(names: Iterable[str]) -> list[Package]:
    """Fetch multiple packages concurrently, preserving input order."""
    names = list(names)
    return list(await asyncio.gather(*(aget_package(name) for name in names)))
